<dl><dt>מקור</dt><dd><?=e($p['source_url']??'')?></dd><dt>מיקום</dt><dd><?=e((string)($p['latitude']??'').' , '.(string)($p['longitude']??''))?></dd><dt>מזהה קבוע</dt><dd><?=e($r['id'])?></dd><dt>שפה</dt><dd><?=e($p['language']??'he')?></dd></dl>
<?php if($r['state']==='merged'&&socialQuery("SELECT 1 FROM network_place_merges WHERE source=? AND state='active'",[$r['id']])->fetchColumn()):?><form method="post"><?=csrf()?><input type="hidden" name="expected_version" value="<?=e(networkReviewVersion('place',$r['id']))?>"><input type="hidden" name="kind" value="place"><input type="hidden" name="id" value="<?=e($r['id'])?>"><label>סיבת ביטול האיחוד<input name="moderator_note" minlength="10" maxlength="500" required></label><button name="decision" value="unmerge">ביטול איחוד ושחזור מצב הפרסום הקודם</button></form><p>הפניות ששמרו את המזהה המקורי יחזרו למקום זה. עותקים שכבר נשמרו במזהה המאוחד נשארים כפי שנשמרו.</p><?php endif?>
<?php $duplicates=networkDuplicates($p,$r['id']);if($duplicates):?><h4>חשד לכפילות — דורש בדיקה אנושית</h4><ul><?php foreach($duplicates as $candidate):?><li><?=e($candidate['title'].' · '.$candidate['id'].' · '.$candidate['state'])?></li><?php endforeach?></ul>
<?php if(array_filter($duplicates,fn($d)=>$d['state']==='approved')):?><form method="post"><?=csrf()?><input type="hidden" name="expected_version" value="<?=e(networkReviewVersion('place',$r['id']))?>"><input type="hidden" name="kind" value="place"><input type="hidden" name="id" value="<?=e($r['id'])?>"><input type="hidden" name="decision" value="merge"><label>איחוד אל רשומה מאושרת<select name="merge_target"><?php foreach($duplicates as $candidate)if($candidate['state']==='approved'):?><option value="<?=e($candidate['id'])?>"><?=e($candidate['title'])?></option><?php endif?></select></label><label>הסבר<input name="moderator_note" maxlength="500"></label><button>איחוד ושמירת הפניות קיימות</button></form><?php endif;endif?>

<?php if(!empty($p['offer'])): ?><h4>פרטי ספק ומחיר לבדיקה</h4><pre><?=e(json_encode($p['offer'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre><?php endif ?>
